        const c = add('Tags', tg, true), fit = () => { c.classList.remove('wide'); tg.style.width = 'max-content'; const over = tg.offsetWidth > c.clientWidth; tg.style.width = ''; c.classList.toggle('wide', over); };
        fit(); new ResizeObserver(fit).observe(f);
