    return `<span class="stars${sm ? ' sm' : ''}${mine ? ' mine' : ''}${can ? ' rt' : ''}" data-tip="${esc(tip)}" aria-label="${esc(avg)}">${[1, 2, 3, 4, 5].map(st).join('')}</span>`;
