/* ── artwork ───────────────────────────────────────── */
function artHtml(r) {
    // a lone front cover is already the header's picture
    if (!r.images.length || (r.images.length === 1 && r.images[0].types.length === 1 && r.images[0].types[0] === 'Front')) return '';
    const body = `<div class="artgrid">${r.images.map(i => `<figure><a href="${esc(i.image)}" target="_blank" rel="noopener"><img src="${esc(thumbOf(i))}" data-full="${esc(i.image)}" data-artimg alt="" loading="lazy"></a><figcaption>${esc([i.types.join(', '), i.comment].filter(Boolean).join(' · ') || 'Untyped')}</figcaption></figure>`).join('')}</div>`;
    const n = `${r.images.length} image${r.images.length === 1 ? '' : 's'}`;
    return sect('art', 'Artwork', `<span class="aside">${n}</span>`, body, `<div class="folded-note">${n}</div>`);
}

/* ── page ──────────────────────────────────────────── */
// Hexagon background: still outlines, and the motion the settings choose over them.
// the effects' strength next to Drift's, so one Effect opacity reads the same in each
const HEX_MF = { drift: 1, tide: .8, twinkle: 1.16, ripple: 1.24, lantern: 1.16, neural: 1.78, electricity: 2.22 };
const HEX_JS = ['twinkle', 'ripple', 'lantern', 'electricity', 'neural'];
